# 180-degree rotation: N<->S, E<->W
perm=np.arange(46)
def sw(a,b):
    perm[a],perm[b]=b,a
for k in range(3):
    for off in (0,12):
        sw(off+0*3+k, off+2*3+k); sw(off+1*3+k, off+3*3+k)
for k in range(2):
    for off in (24,32):
        sw(off+0*2+k, off+2*2+k); sw(off+1*2+k, off+3*2+k)
